#!/usr/bin/env python3
"""Build static pages from shared configuration; no Node runtime required."""
import json, html, re
from pathlib import Path
from urllib.parse import urlparse
R=Path(__file__).resolve().parents[1]; P=R/'public'
c=json.loads((R/'config/company.json').read_text()); works=[w for w in json.loads((R/'config/portfolio.json').read_text()) if w.get('published')]
e=lambda s:html.escape(str(s),quote=True)
domain=c['domain'].rstrip('/')
if domain and (urlparse(domain).scheme!='https' or not urlparse(domain).netloc):raise ValueError('domain must be an HTTPS origin')
phone=re.sub(r'\D','',c['phone']); phone_link=('+'+phone if re.fullmatch(r'7\d{10}',phone) else '')
def contacts():
 phone_html=f'<a href="tel:{phone_link}" data-goal="phone_click">{e(c["phone"])}</a>' if phone_link else e(c['phone'])
 tg=c['telegram']; tg_html=f'<p><a href="{e(tg)}" data-goal="telegram_click">Telegram</a></p>' if re.fullmatch(r'https://t\.me/[A-Za-z0-9_]{5,}',tg) else ''
 return f'<div class="contact-list"><p>{phone_html}</p><p>{e(c["email"])}</p><p>{e(c["city"])} · {e(c["area"])}</p><p>{e(c["address"])}</p><p>{e(c["hours"])}</p>{tg_html}</div>'
nav=[('/', 'Главная')]+[('/'+s['slug']+'/',s['title']) for s in c['services']]+([('/raboty/','Примеры работ')] if works else [])+[('/kontakty/','Контакты')]
form='''<section class="section contact-section" id="zayavka"><div class="wrap form-layout"><div><p class="eyebrow">Обсудим вашу задачу</p><h2>Начнём с разговора</h2><p>Оставьте номер телефона и расскажите, какой баннер вам нужен.</p><p class="muted">Стоимость рассчитывается индивидуально.</p>CONTACTS</div><form id="callback"><label class="field">Имя <span class="muted">· необязательно</span><input name="name" maxlength="100" autocomplete="given-name" aria-describedby="name-error"><span class="error" id="name-error" data-error="name"></span></label><label class="field">Телефон<input name="phone" type="tel" required maxlength="40" autocomplete="tel" placeholder="+7 (___) ___-__-__" aria-describedby="phone-error"><span class="error" id="phone-error" data-error="phone"></span></label><label class="field">Комментарий · необязательно<textarea name="comment" maxlength="1000" rows="4" aria-describedby="comment-error"></textarea><span class="error" id="comment-error" data-error="comment"></span></label><label class="hp" aria-hidden="true">Сайт<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input type="checkbox" name="consent" required aria-describedby="consent-error"><span>Я даю <a href="/soglasie/">согласие на обработку персональных данных</a>. <a href="/politika/">Политика обработки</a>.</span></label><p class="error" id="consent-error" data-error="consent"></p><button type="submit">Заказать звонок</button><p class="status" role="status" aria-live="polite"></p></form></div></section>'''.replace('CONTACTS',contacts())
if phone_link:
 form=form.replace('</form>',f'<p>Если отправка недоступна, <a href="tel:{phone_link}" data-goal="phone_click">позвоните нам</a>.</p></form>')
def gallery():
 out=''
 for w in works:
  imgs=''
  for im in w['images']:
   path=im['src']
   if not path.startswith('/assets/images/work/') or '..' in path or not (P/path.lstrip('/')).is_file():raise ValueError('Invalid portfolio image')
   imgs+=f'<img src="{e(path)}" alt="{e(im["alt"])}" width="{int(im["width"])}" height="{int(im["height"])}" loading="lazy" decoding="async">'
  out+=f'<article class="card gallery">{imgs}<h3>{e(w["title"])}</h3><p>{e(w["description"])}</p></article>'
 return '<div class="grid">'+out+'</div>'
def page(path,title,description,body,noindex=False):
 canonical=f'<link rel="canonical" href="{e(domain+path)}"><meta property="og:url" content="{e(domain+path)}">' if domain else ''
 metrics=''
 if re.fullmatch(r'[1-9]\d*',str(c['metrikaId'])):
  metrics=f'''<script src="https://mc.yandex.ru/metrika/tag.js" defer></script><script src="/assets/metrics.js" defer></script>'''
  (P/'assets/metrics.js').write_text(f"window.bannerMetrika={int(c['metrikaId'])};window.ym=window.ym||function(){{(ym.a=ym.a||[]).push(arguments)}};ym.l=Date.now();ym(window.bannerMetrika,'init',{{clickmap:false,trackLinks:false,accurateTrackBounce:true,webvisor:false,defer:true,params:{{}}}});ym(window.bannerMetrika,'hit',location.origin+location.pathname,{{referer:location.origin}});")
 structured=''
 if '[' not in c['name']:
  structured='<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@type':'Organization','name':c['name'],'areaServed':{'@type':'Country','name':'Россия'}},ensure_ascii=False).replace('<','\\u003c')+'</script>'
 document=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} — {e(c['name'])}</title><meta name="description" content="{e(description)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><meta property="og:locale" content="ru_RU">{structured}{canonical}{'<meta name="robots" content="noindex">' if noindex else ''}<link rel="stylesheet" href="/assets/site.css"><script src="/assets/site.js" defer></script>{metrics}</head><body><a href="#main" class="skip">К содержимому</a><header><div class="wrap"><a class="brand" href="/">{e(c['name'])}</a><span>{f'<a href="tel:{phone_link}" data-goal="phone_click">{e(c["phone"])}</a>' if phone_link else e(c['phone'])}</span><a class="button header-cta" href="/#zayavka">Заказать звонок</a><nav aria-label="Основная навигация">{''.join(f'<a href="{u}">{e(t)}</a>' for u,t in nav)}</nav></div></header><main id="main">{body}</main><footer><div class="wrap"><span>{e(c['name'])} · Россия</span><a href="/politika/">Политика обработки данных</a><a href="/soglasie/">Согласие</a></div></footer></body></html>'''
 target=P/('index.html' if path=='/' else '404.html' if path=='/404.html' else path.strip('/')+'/index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(document)
cards='<div class="grid">'+''.join(f'<article class="card"><span class="number">0{i+1} / УСЛУГА</span><h3><a href="/{e(s["slug"])}/">{e(s["title"])}</a></h3><p>{e(s["description"])}</p></article>' for i,s in enumerate(c['services']))+'</div>'
home='''<div class="wrap hero"><div><p class="eyebrow">Производство · печать · установка</p><h1>Вашу рекламу<br>будет видно.</h1><p class="lead">Изготавливаем и устанавливаем рекламные баннеры. Обсудим задачу, согласуем детали и подготовим решение для вашего места размещения.</p><a class="button" href="#zayavka">Обсудить заказ</a><p class="muted">Россия · CITY</p></div><div class="hero-art" role="img" aria-label="Графическая иллюстрация рекламного баннера"><div class="banner-art">МЕСТО<br>ДЛЯ ВАШЕЙ<br>РЕКЛАМЫ<small>ИДЕЯ → ПЕЧАТЬ → МОНТАЖ</small></div><span class="art-note">Иллюстрация · не пример выполненной работы</span></div></div><section class="section"><div class="wrap"><p class="eyebrow">Что мы делаем</p><h2>От изготовления до установки</h2>CARDS</div></section>'''.replace('CITY',e(c['city'])).replace('CARDS',cards)
if works:home+='<section class="section"><div class="wrap"><h2>Примеры работ</h2>'+gallery()+'</div></section>'
home+='''<section class="section"><div class="wrap"><p class="eyebrow">Понятный процесс</p><h2>Пять шагов к размещению</h2><ol class="steps"><li>Заявка</li><li>Уточнение задачи</li><li>Согласование</li><li>Изготовление</li><li>Монтаж</li></ol></div></section><section class="section"><div class="wrap"><h2>От чего зависит стоимость</h2><p>Стоимость рассчитывается индивидуально.</p><div class="tags"><span>Размер</span><span>Материал</span><span>Обработка краёв</span><span>Крепления</span><span>Условия монтажа</span></div></div></section><section class="section"><div class="wrap"><h2>Вопросы перед заказом</h2><details><summary>Что нужно для расчёта?</summary><p>Сообщите размеры, место размещения и пожелания. Если есть макет или фото места — обсудим их при обратном звонке.</p></details><details><summary>Сколько стоит изготовление?</summary><p>Стоимость рассчитывается индивидуально после уточнения параметров баннера и условий монтажа.</p></details><details><summary>Какие сроки изготовления?</summary><p>Сроки согласовываются после уточнения объёма и требований к заказу.</p></details></div></section>'''+form
page('/','Изготовление и монтаж рекламных баннеров','Производство, печать и установка рекламных баннеров в России. Обсудите задачу и закажите обратный звонок.',home)
for s in c['services']:page('/'+s['slug']+'/',s['title'],s['description']+' Стоимость рассчитывается индивидуально.',f'<div class="wrap legal"><p class="eyebrow">Услуги</p><h1>{e(s["title"])}</h1><p class="lead">{e(s["description"])}</p><h2>Обсудим детали</h2><p>Для расчёта нужны размеры, требования к материалу, макет и условия размещения. Обработка краёв и крепления согласовываются отдельно в составе задания.</p><p>Стоимость рассчитывается индивидуально. Сроки и состав работ фиксируются при согласовании заказа.</p><a class="button" href="#zayavka">Обсудить заказ</a></div>'+form)
page('/kontakty/','Контакты','Свяжитесь с компанией для обсуждения изготовления и установки баннеров.',f'<div class="wrap legal"><h1>Контакты</h1>{contacts()}<h2>Реквизиты</h2><p>{e(c["details"])}</p></div>'+form)
for slug,title,content in [('politika','Политика обработки персональных данных','''<h2>Оператор и цели</h2><p>Оператор: DETAILS. Адрес: ADDRESS. Контакт для обращений: EMAIL. Данные обрабатываются для обратного звонка, обсуждения и исполнения заказа.</p><h2>Состав данных и операции</h2><p>Имя (при указании), телефон, комментарий, страница и рекламные метки, время и версия согласия. Операции: сбор, запись, хранение, использование для связи, удаление. Технический ограничитель частоты использует временный хеш сетевого адреса.</p><h2>Хранение и получатели</h2><p>База размещается в России: [провайдер и адрес размещения]. Срок хранения: [согласованный срок]. Почтовый провайдер: [название и условия]. В Telegram направляются только номер заявки и техническое состояние письма. Уточнить перечень обработчиков и применимость требований к передаче данных.</p><h2>Права и обращения</h2><p>Для доступа, уточнения, удаления данных или отзыва согласия обратитесь к оператору по указанному контакту. Оператор рассматривает обращения в применимые законные сроки. После достижения цели данные удаляются, если нет иного законного основания хранения.</p>'''),('soglasie','Согласие на обработку персональных данных','''<p>Я добровольно даю оператору DETAILS, адрес ADDRESS, согласие на обработку указанных мною имени, телефона и комментария, а также страницы отправки, рекламных меток и сведений о согласии для обратной связи и обсуждения заказа.</p><p>Разрешённые действия: сбор, запись, хранение, использование для связи, уточнение и удаление с применением средств автоматизации. Получатели и условия поручения: [уточнить российский хостинг и почтового провайдера].</p><p>Согласие действует [срок или событие прекращения]. Его можно отозвать обращением на EMAIL. Порядок прекращения обработки и удаления определяется применимыми требованиями и иными законными основаниями.</p>''')]:
 content=content.replace('DETAILS',e(c['details'])).replace('ADDRESS',e(c['address'])).replace('EMAIL',e(c['email']))
 page('/'+slug+'/',title,title+' — проект документа для заполнения оператором.',f'<div class="wrap legal"><h1>{title}</h1><p class="notice">Проект. Требует заполнения и юридической проверки до публикации. Версия: {e(c["consentVersion"])}</p>{content}</div>')
if works:page('/raboty/','Примеры работ','Фотографии выполненных работ компании.','<div class="wrap section"><h1>Примеры работ</h1>'+gallery()+'</div>')
elif (P/'raboty/index.html').exists():(P/'raboty/index.html').unlink()
page('/404.html','Страница не найдена','Запрошенная страница не найдена.','<div class="wrap legal"><h1>Страница не найдена</h1><a class="button" href="/">На главную</a></div>',True)
paths=[u for u,t in nav]+['/politika/','/soglasie/']
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+(''.join('<url><loc>'+e(domain+p)+'</loc></url>' for p in paths) if domain else '')+'</urlset>')
(P/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nDisallow: /api/\nSitemap: '+domain+'/sitemap.xml\n' if domain else 'Disallow: /\n'))
print('Static pages generated; '+('domain configured' if domain else 'indexing disabled until domain is configured'))
